/** Runs every step in order. Each call owns its output and drift state. */
export async function runFlow(page: Page, vars: Vars, options: RunOptions = {}): Promise<Outputs> {
  validateInputs(vars);
  const run = options.run ?? createFlowRun();
  run.outputs = {};
  run.drift.length = 0;
  run.echoed = [];
  run.created = [];
  run.warnings = [];
  const outputs = run.outputs;
  try {
    const browserMismatch = profileMismatch(RECORDED_BROWSER, await readLiveBrowser(page));
    if (browserMismatch) {
      run.warnings.push(browserMismatch);
      console.log(`[sitelooper warn] ${browserMismatch}`);
    }
    // Traffic is recorded from the start url on, as the daemon records it from adopting the page.
    pageTraffic(page);
    await page.goto(options.startUrl ?? 'http://127.0.0.1:8096/', { waitUntil: 'load', timeout: GOTO_TIMEOUT_MS });
    await waitForContent(page).catch(() => {});
    await startPageSettled(page).catch(() => {});
    await test.step('01-open: Open http://127.0.0.1:8096/ and sign in with username \'admin\' and password \'bench-admin-pass\'. Then navigate to the project named \'Bench Project\' and list the titles of all tasks whose title starts with \'Seed:\' exactly as displayed. Report those titles verbatim, one per line.', async () => {
      await steps['01-open'](page, { v1: 'http://127.0.0.1:8096/', v2: 'admin', v3: 'bench-admin-pass' }, outputs, run);
      console.log('[sitelooper step] 01-open');
    });
    await test.step('02-open: In the Vikunja project \'Bench Project\' (already open at {{01-open.url}}), create a new task titled exactly \'{{runid}} Bench Task\'. Set its description to text that includes the runid \'{{runid}}\' (e.g. \'Bench task for run {{runid}}\'). Save the task. Then open the task\'s own detail page and report the task\'s title, its description text, and the identifier the app displays for it (Vikunja shows it as BENCH-<number>).', async () => {
      await steps['02-open'](page, { v1: 'Bench Project', v2: outputs['01-open.url'] ?? '', v3: vars.runid, v4: `${vars.runid} Bench Task`, v5: `Bench task for run ${vars.runid}` }, outputs, run);
      console.log('[sitelooper step] 02-open');
    });
    await test.step('03-open: On the Vikunja task detail page for the task \'{{runid}} Bench Task\' (currently open at {{02-open.url}}), set the task\'s due date to 2026-12-31 (December 31, 2026) and set its priority to \'High\'. The page edits fields in place and saves automatically. Verify both changes persisted by re-reading the page, and report the due date and priority exactly as displayed.', async () => {
      await steps['03-open'](page, { v1: `${vars.runid} Bench Task`, v2: vars.runid, v3: need(outputs, '02-open.url', '03-open'), v4: 'December', v5: 'High' }, outputs, run);
      console.log('[sitelooper step] 03-open');
    });
    await test.step('04-open: On the Vikunja task detail page for the task \'{{runid}} Bench Task\' (currently open at {{02-open.url}}), add a label to the task. IMPORTANT: the label field creates a NEW label from typed text, so you must instead open the label control and choose the EXISTING label named \'Backend\' from its suggestions/dropdown list — do not type-and-create a new one. After selecting, verify the task now shows the label \'Backend\' and report exactly what label(s) are displayed on the task page.', async () => {
      await steps['04-open'](page, { v1: `${vars.runid} Bench Task`, v2: vars.runid, v3: need(outputs, '02-open.url', '04-open') }, outputs, run);
      console.log('[sitelooper step] 04-open');
    });
    await test.step('05-open: On the Vikunja task detail page for the task \'{{runid}} Bench Task\' (currently open at {{02-open.url}}), add a comment to the task whose text includes the runid \'{{runid}}\' (e.g. \'Comment for run {{runid}}\'). Submit the comment. Then verify it was posted by re-reading the comments section after a page reload, and report the comment text exactly as displayed.', async () => {
      await steps['05-open'](page, { v1: `${vars.runid} Bench Task`, v2: vars.runid, v3: need(outputs, '02-open.url', '05-open'), v4: `Comment for run ${vars.runid}` }, outputs, run);
      console.log('[sitelooper step] 05-open');
    });
    await test.step('06-report: Final verification pass in Vikunja at http://127.0.0.1:8096. First, reload the task detail page at {{02-open.url}} and report: the task\'s identifier (BENCH-<number>), its title, its description text, its due date, its priority, its label(s), and the text of its comment(s). Then go to the project \'Bench Project\' ({{01-open.url}}) and report the full list of task titles shown in the project, verbatim, so I can confirm the three \'Seed:\' tasks are still present and unmodified.', async () => {
      await steps['06-report'](page, { v1: need(outputs, '02-open.url', '06-report'), v2: 'Bench Project', v3: need(outputs, '01-open.url', '06-report'), v4: vars.runid }, outputs, run);
      console.log('[sitelooper step] 06-report');
    });
    return outputs;
  } finally {
    DRIFT.splice(0, DRIFT.length, ...run.drift);
  }
}
